    private LinearLayout.LayoutParams toolParams(){return new LinearLayout.LayoutParams(0,dp(61),1);}
    private static String dailyName(int kind){return kind==DailyContent.HISTORY?"今日历史":kind==DailyContent.BRIEF?"科技与 AI 简报":kind==DailyContent.DAILY?"每日语录与书籍":"动漫人物生日";}
